import numpy as np
g=9.8
C={'sphere':0.735,'cube':2.109,'cylinder':1.277}
def sim(m,r,sh,h,v,a,rho,dt=1e-4):
    k=C[sh]*rho*r*r/m
    x=0;y=h;vx=v*np.cos(np.radians(a));vy=v*np.sin(np.radians(a));t=0
    while True:
        s=np.hypot(vx,vy)
        ax=-k*s*vx;ay=-g-k*s*vy
        vx+=ax*dt;vy+=ay*dt;xn=x+vx*dt;yn=y+vy*dt;t+=dt
        if yn<=0:
            f=y/(y-yn);return t-dt+f*dt,x+f*(xn-x),np.hypot(vx,vy)
        x,y=xn,yn
for args in [(0.2,.15,'sphere',10,15,45,1.2),(0.2,.15,'sphere',10,15,-45,1.2),(0.2,.15,'sphere',10,15,90,1.2),(3,.05,'cube',30,20,30,1.2),(1,.1,'sphere',10,10,30,0),(0.2,.15,'sphere',50,0,0,1.2)]:
    print(args,sim(*args))

